async def finish(self, timeout: float = 15.0) -> str:
    """发送结束帧, 接收最终识别结果。

    N10: 接收循环带超时 — 服务端不返回 status=2 时不再永久挂起。
    """
    if not self._ws:
        return ""

    # 结束帧
    end_frame = {
        "data": {
            "status": 2,  # 2=结束
            "format": "audio/L16;rate=16000",
            "encoding": "raw",
            "audio": "",
        }
    }
    await self._ws.send(json.dumps(end_frame))

    # 接收结果
    full_text = []
    try:
        while True:
            try:
                msg = await asyncio.wait_for(self._ws.recv(), timeout=timeout)
            except asyncio.TimeoutError:
                logger.warning(f"[stt] receive timeout after {timeout}s")
                break
            resp = json.loads(msg)
            if resp.get("code") != 0:
                logger.warning(f"[stt] error: {resp}")
                break
            data = resp.get("data", {})
            result = data.get("result", {})
            # ws 字段含动态修正结果
            ws = result.get("ws", [])
            for w in ws:
                cw = w.get("cw", [])
                for c in cw:
                    word = c.get("w", "")
                    if word:
                        full_text.append(word)
            # 检查是否结束
            if data.get("status") == 2:
                break
    except Exception as e:
        logger.error(f"[stt] receive error: {e}")
    finally:
        await self._ws.close()

